803: static float PanelDist(V3 hinge, float phiDeg, float width, V3 p) {
804:     const float c = cosf(phiDeg * 0.0174532925f), s = sinf(phiDeg * 0.0174532925f);
805:     const float px = p.x - hinge.x, py = p.y - hinge.y;
806:     float t = px * c + py * s; if (t < 0.0f) t = 0.0f; if (t > width) t = width;
807:     const float dx = px - c * t, dy = py - s * t;
808:     return sqrtf(dx * dx + dy * dy);
809: }
