119: // A control named right after a noun reads as a label ("Notebook (the Menu button)"); after a verb
120: // or a conjunction it is the object ("press X", "hold the left trigger or the right trigger").
121: static bool AfterVerb(const wchar_t* s, size_t at) {
122:     size_t e = at;
123:     while (e > 0 && s[e - 1] == L' ') --e;
124:     size_t b = e;
125:     while (b > 0 && iswalpha(s[b - 1])) --b;
126:     if (b == e) return true;   // start of the text, or after punctuation
127:     static const wchar_t* kWords[] = { L"press", L"pressing", L"hold", L"holding", L"with", L"down",
128:                                        L"and", L"or", L"use", L"squeeze", L"tap" };
129:     for (const wchar_t* w : kWords)
130:         if (wcslen(w) == e - b && _wcsnicmp(s + b, w, e - b) == 0) return true;
131:     return false;
132: }
133: // Returns true when the text changed (out then holds the new text).
134: static bool Rewrite(const wchar_t* s, size_t len, wchar_t* out, size_t cap) {
135:     const bool mouseLayout = OLProxy_MouseUseEnabled() && !OLUE3_InGameMenu();
136:     for (const Sentence& st : kSentences) {
137:         if (wcslen(st.game) == len && wcsncmp(s, st.game, len) == 0 && GateOn(st.gate)) {
138:             size_t n = 0;
139:             const wchar_t* text = mouseLayout && st.mouseQuest ? st.mouseQuest : st.quest;
140:             return Put(out, cap, &n, text, wcslen(text));
141:         }
142:     }
143:     bool changed = false; size_t n = 0; out[0] = 0;
144:     for (size_t i = 0; i < len;) {
145:         if (s[i] == L'{' && i + 5 <= len && wcsncmp(s + i, L"{OLA_", 5) == 0) {
146:             size_t j = i + 5;
147:             while (j < len && s[j] != L'}' && j - i < 48) ++j;
148:             if (j < len && s[j] == L'}') {
149:                 const wchar_t* name = s + i + 5; const size_t nl = j - (i + 5);
150:                 const wchar_t* quest = nullptr;
151:                 for (const ActionWord& a : kActions)
152:                     if (wcslen(a.action) == nl && wcsncmp(name, a.action, nl) == 0) { quest = a.quest; break; }
153:                 if (quest) {
154:                     if (mouseLayout && nl == 3 && wcsncmp(name, L"Use", nl) == 0) quest = L"B";
155:                     if (mouseLayout && ((nl == 6 && wcsncmp(name, L"Crouch", nl) == 0) ||
156:                         (nl == 12 && wcsncmp(name, L"CrouchToggle", nl) == 0))) quest = L"X";
157:                     const bool bare = AfterVerb(s, i);
158:                     if (!bare && !Put(out, cap, &n, L"(", 1)) return false;
159:                     if (!Put(out, cap, &n, quest, wcslen(quest))) return false;
160:                     if (!bare && !Put(out, cap, &n, L")", 1)) return false;
161:                     changed = true; i = j + 1;
162:                     continue;
163:                 }
164:             }
165:         }
166:         if (!Put(out, cap, &n, s + i, 1)) return false;
167:         ++i;
168:     }
169:     return changed;
170: }
